



"use strict";









const CHAR_UPPERCASE_A = 65;
const CHAR_UPPERCASE_Z = 90;
const CHAR_LOWERCASE_A = 97;
const CHAR_LOWERCASE_Z = 122;
const CHAR_DOT = 46;
const CHAR_FORWARD_SLASH = 47;
const CHAR_BACKWARD_SLASH = 92;
const CHAR_COLON = 58;





const isPosixPathSeparator = (code) => code === CHAR_FORWARD_SLASH;





const isPathSeparator = (code) =>
	code === CHAR_FORWARD_SLASH || code === CHAR_BACKWARD_SLASH;





const isWindowsDeviceRoot = (code) =>
	(code >= CHAR_UPPERCASE_A && code <= CHAR_UPPERCASE_Z) ||
	(code >= CHAR_LOWERCASE_A && code <= CHAR_LOWERCASE_Z);










function normalizeString(path, allowAboveRoot, separator, isSeparator) {
	let res = "";
	let lastSegmentLength = 0;
	let lastSlash = -1;
	let dots = 0;
	let code = 0;
	for (let i = 0; i <= path.length; ++i) {
		if (i < path.length) {
			code = path.charCodeAt(i);
		} else if (isSeparator(code)) {
			break;
		} else {
			code = CHAR_FORWARD_SLASH;
		}

		if (isSeparator(code)) {
			if (lastSlash === i - 1 || dots === 1) {
				
			} else if (dots === 2) {
				if (
					res.length < 2 ||
					lastSegmentLength !== 2 ||
					res.charCodeAt(res.length - 1) !== CHAR_DOT ||
					res.charCodeAt(res.length - 2) !== CHAR_DOT
				) {
					if (res.length > 2) {
						const lastSlashIndex = res.lastIndexOf(separator);
						if (lastSlashIndex === -1) {
							res = "";
							lastSegmentLength = 0;
						} else {
							res = res.slice(0, lastSlashIndex);
							lastSegmentLength = res.length - 1 - res.lastIndexOf(separator);
						}
						lastSlash = i;
						dots = 0;
						continue;
					} else if (res.length !== 0) {
						res = "";
						lastSegmentLength = 0;
						lastSlash = i;
						dots = 0;
						continue;
					}
				}
				if (allowAboveRoot) {
					res += res.length > 0 ? `${separator}..` : "..";
					lastSegmentLength = 2;
				}
			} else {
				if (res.length > 0) {
					res += `${separator}${path.slice(lastSlash + 1, i)}`;
				} else {
					res = path.slice(lastSlash + 1, i);
				}
				lastSegmentLength = i - lastSlash - 1;
			}
			lastSlash = i;
			dots = 0;
		} else if (code === CHAR_DOT && dots !== -1) {
			++dots;
		} else {
			dots = -1;
		}
	}
	return res;
}





function posixNormalize(path) {
	if (path.length === 0) return ".";

	const isAbsolute = path.charCodeAt(0) === CHAR_FORWARD_SLASH;
	const trailingSeparator =
		path.charCodeAt(path.length - 1) === CHAR_FORWARD_SLASH;

	path = normalizeString(path, !isAbsolute, "/", isPosixPathSeparator);

	if (path.length === 0) {
		if (isAbsolute) return "/";
		return trailingSeparator ? "./" : ".";
	}
	if (trailingSeparator) path += "/";

	return isAbsolute ? `/${path}` : path;
}





function posixDirname(path) {
	if (path.length === 0) return ".";
	const hasRoot = path.charCodeAt(0) === CHAR_FORWARD_SLASH;
	let end = -1;
	let matchedSlash = true;
	for (let i = path.length - 1; i >= 1; --i) {
		if (path.charCodeAt(i) === CHAR_FORWARD_SLASH) {
			if (!matchedSlash) {
				end = i;
				break;
			}
		} else {
			matchedSlash = false;
		}
	}

	if (end === -1) return hasRoot ? "/" : ".";
	if (hasRoot && end === 1) return "//";
	return path.slice(0, end);
}













function win32Normalize(path) {
	const len = path.length;
	if (len === 0) return ".";
	let rootEnd = 0;
	
	let device;
	let isAbsolute = false;
	const code = path.charCodeAt(0);

	if (len === 1) {
		return isPosixPathSeparator(code) ? "\\" : path;
	}

	if (isPathSeparator(code)) {
		
		isAbsolute = true;

		if (isPathSeparator(path.charCodeAt(1))) {
			
			let j = 2;
			let last = j;
			while (j < len && !isPathSeparator(path.charCodeAt(j))) j++;
			if (j < len && j !== last) {
				const firstPart = path.slice(last, j);
				last = j;
				while (j < len && isPathSeparator(path.charCodeAt(j))) j++;
				if (j < len && j !== last) {
					last = j;
					while (j < len && !isPathSeparator(path.charCodeAt(j))) j++;
					if (j === len || j !== last) {
						if (firstPart === "." || firstPart === "?") {
							
							device = `\\\\${firstPart}`;
							rootEnd = 4;
						} else if (j === len) {
							
							return `\\\\${firstPart}\\${path.slice(last)}\\`;
						} else {
							
							device = `\\\\${firstPart}\\${path.slice(last, j)}`;
							rootEnd = j;
						}
					}
				}
			}
		} else {
			rootEnd = 1;
		}
	} else if (isWindowsDeviceRoot(code) && path.charCodeAt(1) === CHAR_COLON) {
		
		device = path.slice(0, 2);
		rootEnd = 2;
		if (len > 2 && isPathSeparator(path.charCodeAt(2))) {
			isAbsolute = true;
			rootEnd = 3;
		}
	}

	let tail =
		rootEnd < len
			? normalizeString(path.slice(rootEnd), !isAbsolute, "\\", isPathSeparator)
			: "";
	if (tail.length === 0 && !isAbsolute) tail = ".";
	if (tail.length > 0 && isPathSeparator(path.charCodeAt(len - 1))) {
		tail += "\\";
	}
	if (!isAbsolute && device === undefined && path.includes(":")) {
		
		
		if (
			tail.length >= 2 &&
			isWindowsDeviceRoot(tail.charCodeAt(0)) &&
			tail.charCodeAt(1) === CHAR_COLON
		) {
			return `.\\${tail}`;
		}
		let index = path.indexOf(":");
		do {
			if (index === len - 1 || isPathSeparator(path.charCodeAt(index + 1))) {
				return `.\\${tail}`;
			}
		} while ((index = path.indexOf(":", index + 1)) !== -1);
	}
	if (device === undefined) {
		return isAbsolute ? `\\${tail}` : tail;
	}
	return isAbsolute ? `${device}\\${tail}` : `${device}${tail}`;
}





function win32Dirname(path) {
	const len = path.length;
	if (len === 0) return ".";
	let rootEnd = -1;
	let offset = 0;
	const code = path.charCodeAt(0);

	if (len === 1) {
		return isPathSeparator(code) ? path : ".";
	}

	if (isPathSeparator(code)) {
		
		rootEnd = offset = 1;

		if (isPathSeparator(path.charCodeAt(1))) {
			let j = 2;
			let last = j;
			while (j < len && !isPathSeparator(path.charCodeAt(j))) j++;
			if (j < len && j !== last) {
				last = j;
				while (j < len && isPathSeparator(path.charCodeAt(j))) j++;
				if (j < len && j !== last) {
					last = j;
					while (j < len && !isPathSeparator(path.charCodeAt(j))) j++;
					if (j === len) {
						
						return path;
					}
					if (j !== last) {
						
						rootEnd = offset = j + 1;
					}
				}
			}
		}
	} else if (isWindowsDeviceRoot(code) && path.charCodeAt(1) === CHAR_COLON) {
		rootEnd = len > 2 && isPathSeparator(path.charCodeAt(2)) ? 3 : 2;
		offset = rootEnd;
	}

	let end = -1;
	let matchedSlash = true;
	for (let i = len - 1; i >= offset; --i) {
		if (isPathSeparator(path.charCodeAt(i))) {
			if (!matchedSlash) {
				end = i;
				break;
			}
		} else {
			matchedSlash = false;
		}
	}

	if (end === -1) {
		if (rootEnd === -1) return ".";
		end = rootEnd;
	}
	return path.slice(0, end);
}








function basename(path, suffix) {
	let start = 0;
	let end = -1;
	let matchedSlash = true;

	if (
		suffix !== undefined &&
		suffix.length > 0 &&
		suffix.length <= path.length
	) {
		if (suffix === path) return "";
		let extIdx = suffix.length - 1;
		let firstNonSlashEnd = -1;
		for (let i = path.length - 1; i >= 0; --i) {
			const code = path.charCodeAt(i);
			if (code === CHAR_FORWARD_SLASH) {
				if (!matchedSlash) {
					start = i + 1;
					break;
				}
			} else {
				if (firstNonSlashEnd === -1) {
					matchedSlash = false;
					firstNonSlashEnd = i + 1;
				}
				if (extIdx >= 0) {
					if (code === suffix.charCodeAt(extIdx)) {
						if (--extIdx === -1) {
							end = i;
						}
					} else {
						extIdx = -1;
						end = firstNonSlashEnd;
					}
				}
			}
		}

		if (start === end) {
			end = firstNonSlashEnd;
		} else if (end === -1) {
			end = path.length;
		}
		return path.slice(start, end);
	}
	for (let i = path.length - 1; i >= 0; --i) {
		if (path.charCodeAt(i) === CHAR_FORWARD_SLASH) {
			if (!matchedSlash) {
				start = i + 1;
				break;
			}
		} else if (end === -1) {
			matchedSlash = false;
			end = i + 1;
		}
	}

	if (end === -1) return "";
	return path.slice(start, end);
}

module.exports = {
	basename,
	posix: { normalize: posixNormalize, dirname: posixDirname },
	win32: { normalize: win32Normalize, dirname: win32Dirname },
};
